import{_ as p,o as a,c as e,a5 as n}from"./chunks/framework.Cooo9kuv.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{"标题":"456-批量在pdf指定页面插入指定页面或批量替换pdf指定页面","日期":"2026-04-06T00:00:00.000Z","修改日期":"2026-04-07T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["PDF批处理"],"标签":["批量在指定页面前插入指定页面","批量插入指定pdf","批量插入指定页面","批量替换pdf指定页面"]},"headers":[{"level":3,"title":"使用实例","slug":"使用实例","link":"#使用实例","children":[]},{"level":3,"title":"如下图所示","slug":"如下图所示","link":"#如下图所示","children":[]},{"level":3,"title":"处理后保持与原文件夹结构一样","slug":"处理后保持与原文件夹结构一样","link":"#处理后保持与原文件夹结构一样","children":[]},{"level":3,"title":"系统环境说明","slug":"系统环境说明","link":"#系统环境说明","children":[]},{"level":3,"title":"处理如果出现问题","slug":"处理如果出现问题","link":"#处理如果出现问题","children":[]}],"relativePath":"md/PDF批处理/456-批量在pdf指定页面插入指定页面或批量替换pdf指定页面.md","filePath":"md/PDF批处理/456-批量在pdf指定页面插入指定页面或批量替换pdf指定页面.md"}'),o={name:"md/PDF批处理/456-批量在pdf指定页面插入指定页面或批量替换pdf指定页面.md"};function r(l,t,d,s,f,i){return a(),e("div",null,[...t[0]||(t[0]=[n('<p>批量在pdf中指定页面前插入指定页面，批量插入指定页面到pdf中。</p><p>1、可以批量为指定文件夹下所有pdf进行操作</p><p>2、可以在指定页面前插入相关页面</p><p>2、可以在指定页面后插入相关页面</p><p>3、可以在首页前或尾页后插入相关页面</p><p>4、可以处理奇数页面，在奇数页pdf尾页插入指定页面时期变为偶数页面，方便打印操作</p><p>5、可以替换指定页面，比如对每个pdf页面的第二页进行替换，替换为指定的页面</p><p><strong>注：插入的页面或替换的页面需要为一个pdf文档，比如要在A.pdf中替换第一页，那么需要创建一个pdf文档，里面包含一个页面，这个页面就是后边替换A.pdf中第一页后的页面。</strong></p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250304183942174108478279904.png" alt=""></p><hr><p><strong>程序更新20250310：</strong></p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250310203127174160988788507.png" alt=""></p><h3 id="使用实例" tabindex="-1">使用实例 <a class="header-anchor" href="#使用实例" aria-label="Permalink to &quot;使用实例&quot;">​</a></h3><p>比如在A文件夹下由很多pdf，同时由B、C、D、E...等文件夹，使用该程序可以将A文件夹路径复制到程序pdf所在文件夹路径输入框，</p><p>然后选择一个需要插入的pdf文档，这个pdf文档就是你要插入到A文件夹下所有pdf中的页面，然后选择操作位置，</p><p>运行程序后，会自动在A文件夹下创建一个文件夹，将A文件夹下所有文档处理后放在这个文件夹下，并且保持原A文件夹下所有pdf所在文件夹结构。</p><h3 id="如下图所示" tabindex="-1"><strong>如下图所示</strong> <a class="header-anchor" href="#如下图所示" aria-label="Permalink to &quot;**如下图所示**&quot;">​</a></h3><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250304184621174108518193279.png" alt=""></p><h3 id="处理后保持与原文件夹结构一样" tabindex="-1">处理后保持与原文件夹结构一样 <a class="header-anchor" href="#处理后保持与原文件夹结构一样" aria-label="Permalink to &quot;处理后保持与原文件夹结构一样&quot;">​</a></h3><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250304184813174108529365074.png" alt=""></p><h3 id="系统环境说明" tabindex="-1">系统环境说明 <a class="header-anchor" href="#系统环境说明" aria-label="Permalink to &quot;系统环境说明&quot;">​</a></h3><p>win7及以上64位操作系统</p><h3 id="处理如果出现问题" tabindex="-1">处理如果出现问题 <a class="header-anchor" href="#处理如果出现问题" aria-label="Permalink to &quot;处理如果出现问题&quot;">​</a></h3><p>处理过程中如果出现问题，一般是pdf文件结构问题，需要将pdf进行预处理，解决标准化问题</p><p>使用下方工具可以将pdf批量进行标准化，之后再进行pdf批处理时就不会出现问题了</p><p><a href="https://www.softbangong.top/?id=10" target="_blank" rel="noreferrer">https://www.softbangong.top/?id=10</a></p><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/87.html" target="_blank" rel="noreferrer">https://www.softbangong.com/87.html</a></p>',28)])])}const c=p(o,[["render",r]]);export{_ as __pageData,c as default};
